pub fn identifier(nid: u8) ?ProxyIdentifier {
	if (nid == 0 or nid > max_nid) return null;
	return identifier_table[nid];
}

pub fn actorForSid(sid: []const u8) ?ProxyIdentifier {
	for (identifier_table) |maybe_entry| {
		const entry = maybe_entry orelse continue;
		if (std.mem.eql(u8, entry.sid, sid)) return entry;
	}
	return null;
}

